// Grocery list screen logic (docs/MEALS.md §5–6). Pure (unit-tested): stored rows in, the
// grouped list, progress and the clipboard text out. The list itself is generated by the engine
// (buildGroceryList) and stored by the data layer (useSyncGroceryList).

import { isStaple } from "@/lib/meals/ingredients";
import { CATEGORY_ORDER, groceryAmount, groceryTotals, type GroceryTotals } from "@/lib/meals/engine/grocery";
import { GROCERY_CATEGORY_LABEL, type GroceryCategory } from "@/lib/meals/types";

/** The stored columns this screen reads (a GroceryItem row fits). */
export interface GroceryRow {
  key: string;
  name: string;
  category: string;
  qty: number | null;
  unit: string | null;
  label: string | null;
  est_cost_cad: number | null;
  position: number;
  checked: boolean;
  have: boolean;
  removed: boolean;
  custom: boolean;
}

export const STAPLE_LABEL = "Check you have";

/** Salt, oil, spices: listed to check at home, never counted as a buy. */
export function isStapleRow(r: Pick<GroceryRow, "key" | "label" | "custom">): boolean {
  if (r.custom) return false;
  return isStaple(r.key) || r.label === STAPLE_LABEL;
}

/** "1.2 kg" for generated lines (from qty + unit); a custom line's own amount text. */
export function rowAmount(r: Pick<GroceryRow, "key" | "qty" | "unit" | "custom" | "label">): string {
  if (r.custom) return r.label ?? (r.qty != null ? `${r.qty}${r.unit ? ` ${r.unit}` : ""}` : "");
  if (r.qty == null || !r.unit) return "";
  return groceryAmount(r.key, Number(r.qty), r.unit);
}

/** How to buy it ("3 × 454 g packs"), when that says more than the amount. */
export function rowBuy(r: Pick<GroceryRow, "key" | "qty" | "unit" | "custom" | "label">): string | null {
  if (r.custom || !r.label || r.label === STAPLE_LABEL) return null;
  return r.label === rowAmount(r) ? null : r.label;
}

const ORDER = new Map<string, number>(CATEGORY_ORDER.map((c, i) => [c, i]));
const byAisle = (a: GroceryRow, b: GroceryRow) => (ORDER.get(a.category) ?? 99) - (ORDER.get(b.category) ?? 99) || a.position - b.position || a.name.localeCompare(b.name);

export interface GroceryGroup {
  category: GroceryCategory | "staples";
  label: string;
  items: GroceryRow[];
}

export interface GroceryView {
  /** Aisle groups of things to buy (checked lines stay in place, struck through). */
  groups: GroceryGroup[];
  /** Staples to check at home (salt, oil, spices), not counted as buys. */
  staples: GroceryRow[];
  /** Lines marked "I have this". */
  have: GroceryRow[];
  /** Lines removed from the list (restorable). */
  removed: GroceryRow[];
  /** Buys and how many are in the cart. */
  toBuy: number;
  inCart: number;
}

export function groceryView(rows: readonly GroceryRow[]): GroceryView {
  const sorted = [...rows].sort(byAisle);
  const removed = sorted.filter((r) => r.removed);
  const live = sorted.filter((r) => !r.removed);
  const staples = live.filter((r) => isStapleRow(r) && !r.have);
  const have = live.filter((r) => r.have);
  const buys = live.filter((r) => !r.have && !isStapleRow(r));
  const groups: GroceryGroup[] = [];
  for (const c of CATEGORY_ORDER) {
    const items = buys.filter((r) => r.category === c);
    if (items.length) groups.push({ category: c, label: GROCERY_CATEGORY_LABEL[c], items });
  }
  const other = buys.filter((r) => !ORDER.has(r.category));
  if (other.length) {
    const g = groups.find((x) => x.category === "other");
    if (g) g.items.push(...other);
    else groups.push({ category: "other", label: GROCERY_CATEGORY_LABEL.other, items: other });
  }
  return { groups, staples, have, removed, toBuy: buys.length, inCart: buys.filter((r) => r.checked).length };
}

/** Totals for the stored list: checkout estimate for what's left to buy, the week's food cost vs budget. */
export function rowTotals(rows: readonly GroceryRow[], budgetCad: number | null): GroceryTotals {
  return groceryTotals(
    rows.map((r) => ({ key: r.key, qty: r.qty, unit: r.unit, est_cost_cad: r.est_cost_cad, have: r.have, removed: r.removed, staple: isStapleRow(r) })),
    budgetCad,
  );
}

/** "$124" / "$12.50": whole dollars from $100, cents below. */
export function cad(n: number): string {
  if (!Number.isFinite(n)) return "—";
  const abs = Math.abs(n);
  const s = abs >= 100 ? Math.round(abs).toLocaleString("en-US") : abs.toFixed(2).replace(/\.00$/, "");
  return `${n < 0 ? "−" : ""}$${s}`;
}

/**
 * The list as clean text for the clipboard (Notes, Messages): what's still to buy, by aisle,
 * then the staples to check at home. Lines already in the cart, "I have this" lines and removed
 * lines are left out.
 */
export function groceryText(rows: readonly GroceryRow[], opts: { title: string; totals?: GroceryTotals | null }): string {
  const v = groceryView(rows);
  const out: string[] = [opts.title];
  let any = false;
  for (const g of v.groups) {
    const left = g.items.filter((r) => !r.checked);
    if (!left.length) continue;
    any = true;
    out.push("", g.label.toUpperCase());
    for (const r of left) {
      const amount = rowAmount(r);
      const buy = rowBuy(r);
      out.push(`- ${r.name}${amount ? `: ${amount}` : ""}${buy ? ` (${buy})` : ""}`);
    }
  }
  if (v.staples.length) {
    any = true;
    out.push("", "CHECK YOU HAVE");
    for (const r of v.staples) out.push(`- ${r.name}`);
  }
  if (!any) out.push("", "Nothing left to buy.");
  const t = opts.totals;
  if (t && t.checkoutCad > 0 && v.groups.some((g) => g.items.some((r) => !r.checked))) out.push("", `Estimated total: about ${cad(t.checkoutCad)} (rough Canadian prices)`);
  return out.join("\n");
}
